use verus::prelude::*;

fn is_ascii_alpha(c: char) -> bool {
    ('a' <= c && c <= 'z') || ('A' <= c && c <= 'Z')
}

fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // We interpret the input string as a sequence of Unicode scalar values (chars).
    // The function returns true iff:
    // 1. txt is non-empty
    // 2. the last character is an ASCII alphabetic letter (a-z or A-Z)
    // 3. and either (txt.len()==1) or the character before last is a space ' '

    let chars: Seq<char> = txt.chars().collect();

    if chars.len() == 0 {
        return false;
    }

    let last_char = *chars.index(chars.len() - 1);

    if !is_ascii_alpha(last_char) {
        return false;
    }

    if chars.len() == 1 {
        return true;
    }

    let prev_char = *chars.index(chars.len() - 2);
    prev_char == ' '
}

